def compute(vars):
    us_acres = vars["v1"]
    worldwide_acres = vars["v2"]
    if worldwide_acres == 0:
        return None
    ratio = us_acres / worldwide_acres
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "us_acres": us_acres,
            "worldwide_acres": worldwide_acres,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage",
            },
        },
    }
